import json

def extract_user_text(obj):
    msg = obj.get("message", {})
    content = msg.get("content")
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        texts = []
        for c in content:
            if isinstance(c, dict) and c.get("type") == "text":
                texts.append(c.get("text",""))
        return "\n".join(texts)
    return ""

path = "/home/koby/.claude/projects/-home-koby/13507989-4a8f-4a40-a8b3-d94aeee8e26c.jsonl"
print("=== SESSION A: user messages ===")
with open(path) as f:
    for line in f:
        obj = json.loads(line)
        if obj.get("type") == "user" and not obj.get("isSidechain"):
            msg = obj.get("message",{})
            content = msg.get("content")
            # skip tool_result-only messages
            if isinstance(content, list):
                has_text = any(isinstance(c,dict) and c.get("type")=="text" for c in content)
                if not has_text:
                    continue
            txt = extract_user_text(obj)
            if txt.strip():
                ts = obj.get("timestamp")
                print(f"--- {ts} ---")
                print(txt[:800])
                print()
